import{_ as t,o,c as n,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"LocalSend Settings","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Basic & Network Settings","slug":"_1-basic-network-settings","link":"#_1-basic-network-settings","children":[]},{"level":2,"title":"2. Security, Encryption & Storage","slug":"_2-security-encryption-storage","link":"#_2-security-encryption-storage","children":[]},{"level":2,"title":"3. Sender Window & Workflows","slug":"_3-sender-window-workflows","link":"#_3-sender-window-workflows","children":[]}],"relativePath":"user-guide/settings/localsend.md","filePath":"user-guide/settings/localsend.md","lastUpdated":1791112464000}'),s={name:"user-guide/settings/localsend.md"};function a(i,e,l,c,d,g){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="localsend-settings" tabindex="-1">LocalSend Settings <a class="header-anchor" href="#localsend-settings" aria-label="Permalink to &quot;LocalSend Settings&quot;">​</a></h1><p>Lertaro includes a built-in transmission engine natively compatible with the open-source <a href="https://localsend.org" target="_blank" rel="noreferrer">LocalSend</a> protocol. Without requiring internet access or physical cables, you can share files, directories, and raw text across Windows PCs, Macs, Linux workstations, iPhones, iPads, and Android devices on the same local network. The settings page is located under <strong>Settings → LocalSend</strong>.</p><h2 id="_1-basic-network-settings" tabindex="-1">1. Basic &amp; Network Settings <a class="header-anchor" href="#_1-basic-network-settings" aria-label="Permalink to &quot;1. Basic &amp; Network Settings&quot;">​</a></h2><ul><li><strong>Enable LocalSend Transfer Service</strong>: Master switch. When enabled, Lertaro starts a lightweight background listener and activates the &quot;Send to other devices...&quot; item in the tray context menu.</li><li><strong>Device Name</strong>: The alias broadcast to other devices across the local subnet. Automatically generated from your computer name by default, and fully customizable (e.g. <code>Work Laptop</code>).</li><li><strong>Service Port</strong>: The HTTP/HTTPS listener port (follows the official LocalSend standard default <code>53317</code>). Can be changed if conflicting with other local services.</li></ul><h2 id="_2-security-encryption-storage" tabindex="-1">2. Security, Encryption &amp; Storage <a class="header-anchor" href="#_2-security-encryption-storage" aria-label="Permalink to &quot;2. Security, Encryption &amp; Storage&quot;">​</a></h2><ul><li><strong>Encrypted Transfer (HTTPS)</strong>: Enabled by default. Uses TLS encryption for all cross-device transfers to prevent local packet inspection.</li><li><strong>Receive PIN Code</strong>: Optional PIN (leave blank to disable). When configured, incoming senders must input this PIN before transfers are accepted.</li><li><strong>Auto-Save Files</strong>: When checked, incoming transfers from local devices are automatically accepted and written to disk without prompt dialogs.</li><li><strong>Save Directory</strong>: The destination folder where received files are saved (defaults to the system&#39;s Downloads folder), customizable via the browse button.</li></ul><h2 id="_3-sender-window-workflows" tabindex="-1">3. Sender Window &amp; Workflows <a class="header-anchor" href="#_3-sender-window-workflows" aria-label="Permalink to &quot;3. Sender Window &amp; Workflows&quot;">​</a></h2><ul><li><strong>Hotkey Activation</strong>: Press the default global shortcut <strong><code>Ctrl+S</code></strong> (rebindable under <a href="./hotkeys-page.html"><strong>Settings → Hotkeys</strong></a>) to summon the standalone LocalSend sender window.</li><li><strong>Mode Switching</strong>: Toggle between <strong>[Send Files / Folders]</strong> and <strong>[Send Text]</strong> modes at the top of the sender window.</li><li><strong>Drag-and-Drop Staging</strong>: Drag files directly from Lertaro search results, Quick Panel workspaces, or File Explorer into the sender window. The radar automatically discovers all online devices on the LAN; click any target device card to transmit at wire speed.</li></ul>',8)])])}const p=t(s,[["render",a]]);export{u as __pageData,p as default};
